from calendar import monthrange
from datetime import date, timedelta


def recur(start: str, rule: str, count: int) -> list[str]:
    first = date.fromisoformat(start)
    parts = rule.split()
    kind = parts[0]
    k = int(parts[1])
    weekdays = {
        "MO": 0, "TU": 1, "WE": 2, "TH": 3,
        "FR": 4, "SA": 5, "SU": 6,
    }

    if kind == "DAILY":
        return [
            (first + timedelta(days=i * k)).isoformat()
            for i in range(count)
        ]

    result = []

    if kind == "WEEKLY":
        selected = sorted(weekdays[wd] for wd in parts[2].split(","))
        week_start = first - timedelta(days=first.weekday())

        while len(result) < count:
            for wd in selected:
                candidate = week_start + timedelta(days=wd)
                if candidate >= first:
                    result.append(candidate.isoformat())
                    if len(result) == count:
                        return result
            week_start += timedelta(weeks=k)

    elif kind == "MONTHLY":
        month_index = first.year * 12 + first.month - 1
        number = int(parts[2])
        wd = weekdays[parts[3]] if len(parts) == 4 else None

        while len(result) < count:
            year, month_zero = divmod(month_index, 12)
            month = month_zero + 1
            last_day = monthrange(year, month)[1]

            if wd is None:
                day = last_day if number == -1 else number
            elif number == -1:
                last_weekday = date(year, month, last_day).weekday()
                day = last_day - (last_weekday - wd) % 7
            else:
                first_weekday = date(year, month, 1).weekday()
                day = 1 + (wd - first_weekday) % 7 + 7 * (number - 1)

            if day <= last_day:
                candidate = date(year, month, day)
                if candidate >= first:
                    result.append(candidate.isoformat())

            month_index += k

    elif kind == "YEARLY":
        month, day = map(int, parts[2].split("-"))
        year = first.year

        while len(result) < count:
            if day <= monthrange(year, month)[1]:
                candidate = date(year, month, day)
                if candidate >= first:
                    result.append(candidate.isoformat())
            year += k

    return result
